<template>
  <Teleport to="body">
    <div v-if="show" ref="scrollEl" class="player" :class="[`player--${storyDocument.settings.theme}`, `player--${storyDocument.settings.density}`, { 'player--performance-edit': performanceEditMode }]" :style="playerStyle" @click="advanceFromCanvas">
      <header @click.stop>
        <button @click="started ? stopPlayback() : $emit('close')">← 返回</button>
        <div class="player-title">
          <input v-if="performanceEditMode" v-model="titleDraft" maxlength="120" aria-label="故事名" @change="saveTitle" @keydown.enter.prevent="saveTitle" />
          <strong v-else>{{ storyDocument.title }}</strong>
          <small v-if="performanceEditMode">演出编辑 · 点击消息设置编排</small>
          <small v-else>{{ started ? `${visibleCount} / ${storyDocument.messages.length}` : `${storyDocument.messages.length} 条消息` }}</small>
        </div>
        <div class="player-header-actions">
          <button v-if="!started" :class="{ active: performanceEditMode }" @click="togglePerformanceEdit">演出编辑</button>
          <button class="primary" @click="headerAction">{{ finished ? '重新演出' : !started ? '开始演出' : paused ? '继续演出' : '暂停演出' }}</button>
          <button v-if="started" class="danger-solid" @click="stopPlayback">关闭演出</button>
        </div>
      </header>

      <main :style="canvasStyle">
        <TransitionGroup :name="started && storyDocument.settings.animation !== 'none' ? storyDocument.settings.animation : ''">
          <article v-for="(message, index) in visibleMessages" :key="message.id" class="player-message" :class="[`player-message--${character(message.characterId)?.position || 'left'}`, `player-message--group-${groupPosition(index)}`, { 'player-message--scripted': hasPerformance(message) }]" @click.stop="onMessageClick(message)">
            <span v-if="avatarSlot(message.characterId)" class="player-avatar-slot" :class="{ 'player-avatar-slot--bottom': storyDocument.settings.avatarAlignment === 'bottom' }">
              <span v-if="showAvatar(message.characterId, index)" class="player-avatar"><img v-if="avatar(character(message.characterId))" :src="avatar(character(message.characterId))" alt="" /><i v-else>{{ character(message.characterId)?.name?.slice(0, 1) || '旁' }}</i></span>
            </span>
            <div class="player-message__content">
              <small v-if="showOutsideName(message.characterId, index) || storyDocument.settings.showTime">
                <template v-if="showOutsideName(message.characterId, index)"><span class="character-name" :style="nameStyle(character(message.characterId))">{{ character(message.characterId)?.name }}</span><span v-if="storyDocument.settings.showQqInPreview && character(message.characterId)?.imUserId" class="character-account"> · {{ character(message.characterId)?.imUserId }}</span></template>
                <span v-if="storyDocument.settings.showTime" class="message-time">{{ showOutsideName(message.characterId, index) ? ' · ' : '' }}{{ messageTime(message) }}</span>
              </small>
              <div class="bubble" :class="{ 'bubble--narrator-avatar': showNarratorBubbleAvatar(message.characterId, index) }">
                <div v-if="showNarratorBubbleAvatar(message.characterId, index)" class="narrator-identity"><span class="narrator-avatar"><img v-if="avatar(character(message.characterId))" :src="avatar(character(message.characterId))" alt="" /><i v-else>{{ character(message.characterId)?.name?.slice(0, 1) || '旁' }}</i></span><span v-if="showNarratorName(message.characterId, index)" class="narrator-identity__text"><span class="character-name" :style="nameStyle(character(message.characterId))">{{ character(message.characterId)?.name }}</span><span v-if="storyDocument.settings.showQqInPreview && character(message.characterId)?.imUserId" class="character-account"> · {{ character(message.characterId)?.imUserId }}</span></span></div>
                <img v-if="message.kind === 'image'" class="story-image" :src="imageUrl(message.asset)" :alt="message.alt || '图片'" @click.stop="openImage(message)" />
                <span v-else>{{ renderedText(message) }}</span>
              </div>
              <small v-if="performanceEditMode && hasPerformance(message)" class="performance-summary">{{ performanceSummary(message) }}</small>
            </div>
          </article>
        </TransitionGroup>

        <article v-if="started && phase === 'typing' && typingCharacter" class="typing-indicator" :class="`typing-indicator--${storyDocument.settings.typingIndicatorEffect}`">
          <span class="player-avatar typing-indicator__avatar"><img v-if="avatar(typingCharacter)" :src="avatar(typingCharacter)" alt="" /><i v-else>{{ typingCharacter.name.slice(0, 1) }}</i></span>
          <span class="typing-indicator__bubble"><b>{{ typingCharacter.name }}</b><span>{{ storyDocument.settings.typingIndicatorText || '正在输入' }}</span><span class="typing-dots" aria-hidden="true"><i></i><i></i><i></i></span></span>
        </article>
      </main>

      <footer v-if="!started" @click.stop>
        <button :aria-expanded="performanceSettingsOpen" @click="togglePerformanceSettings">演出设置</button>
        <button :aria-expanded="displaySettingsOpen" @click="toggleDisplaySettings">界面设置</button>

        <section v-if="performanceSettingsOpen" class="settings-panel" aria-label="演出设置">
          <div class="settings-title"><strong>演出设置</strong><span>保存进 SSP 工程包</span></div>
          <label class="switch-row"><span>自动播放</span><n-switch :value="storyDocument.settings.autoplay" @update:value="setSetting('autoplay', $event)" /></label>
          <label>计时方式<n-select :value="storyDocument.settings.playbackTiming" :options="timingOptions" @update:value="setSetting('playbackTiming', $event)" /></label>
          <label v-if="storyDocument.settings.playbackTiming === 'fixed'">默认间隔<n-input-number :value="storyDocument.settings.fixedDelayMs" :min="250" :max="30000" :step="250" @update:value="setSetting('fixedDelayMs', $event ?? 2500)" /><span>ms</span></label>
          <label v-else>阅读速度<n-input-number :value="storyDocument.settings.chineseCharsPerMinute" :min="80" :max="1000" :step="20" @update:value="setSetting('chineseCharsPerMinute', $event ?? 280)" /><span>字/分钟</span></label>
          <label class="switch-row"><span>流式输出</span><n-switch :value="storyDocument.settings.streamEnabled" @update:value="setSetting('streamEnabled', $event)" /></label>
          <label v-if="storyDocument.settings.streamEnabled">输出速度<n-slider :value="storyDocument.settings.streamTokensPerSecond" :min="1" :max="30" :step="1" @update:value="setSetting('streamTokensPerSecond', $event)" /><span>{{ storyDocument.settings.streamTokensPerSecond }} 词/秒</span></label>
          <label v-if="storyDocument.settings.streamEnabled">词后停顿<n-input-number :value="storyDocument.settings.streamPauseMinMs" :min="0" :max="2000" :step="20" @update:value="setSetting('streamPauseMinMs', Math.min($event ?? 0, storyDocument.settings.streamPauseMaxMs))" /><span>—</span><n-input-number :value="storyDocument.settings.streamPauseMaxMs" :min="0" :max="3000" :step="20" @update:value="setSetting('streamPauseMaxMs', Math.max($event ?? 0, storyDocument.settings.streamPauseMinMs))" /><span>ms</span></label>
          <label class="switch-row"><span>正在输入效果</span><n-switch :value="storyDocument.settings.typingIndicatorEnabled" @update:value="setSetting('typingIndicatorEnabled', $event)" /></label>
          <label v-if="storyDocument.settings.typingIndicatorEnabled">提示文本<n-input :value="storyDocument.settings.typingIndicatorText" maxlength="30" @update:value="setSetting('typingIndicatorText', $event)" /></label>
          <label v-if="storyDocument.settings.typingIndicatorEnabled">持续时间<n-input-number :value="storyDocument.settings.typingIndicatorMs" :min="0" :max="10000" :step="100" @update:value="setSetting('typingIndicatorMs', $event ?? 700)" /><span>ms</span></label>
          <label v-if="storyDocument.settings.typingIndicatorEnabled">提示效果<n-select :value="storyDocument.settings.typingIndicatorEffect" :options="typingEffectOptions" @update:value="setSetting('typingIndicatorEffect', $event)" /></label>
        </section>

        <section v-if="displaySettingsOpen" class="settings-panel" aria-label="演出界面设置">
          <div class="settings-title"><strong>界面设置</strong><span>小图保持原始尺寸</span></div>
          <label>角色头像<n-slider :value="storyDocument.settings.avatarSize" :min="24" :max="96" :step="2" @update:value="setSetting('avatarSize', $event)" /><span>{{ storyDocument.settings.avatarSize }}px</span></label>
          <label>旁白头像<n-slider :value="storyDocument.settings.narratorAvatarSize" :min="18" :max="72" :step="2" @update:value="setSetting('narratorAvatarSize', $event)" /><span>{{ storyDocument.settings.narratorAvatarSize }}px</span></label>
          <label>字体<n-slider :value="storyDocument.settings.fontSize" :min="12" :max="32" @update:value="setSetting('fontSize', $event)" /><span>{{ storyDocument.settings.fontSize }}px</span></label>
          <label>气泡上限<n-slider :value="storyDocument.settings.bubbleMaxWidth" :min="45" :max="95" @update:value="setSetting('bubbleMaxWidth', $event)" /><span>{{ storyDocument.settings.bubbleMaxWidth }}%</span></label>
          <label>画布<n-slider :value="storyDocument.settings.canvasWidth" :min="360" :max="1600" :step="20" @update:value="setSetting('canvasWidth', $event)" /><span>{{ storyDocument.settings.canvasWidth }}px</span></label>
          <label>中线留白<n-slider :value="storyDocument.settings.centerGutterPercent" :min="0" :max="24" :step="2" @update:value="setSetting('centerGutterPercent', $event)" /><span>{{ storyDocument.settings.centerGutterPercent }}%</span></label>
          <label>图片宽度上限<n-slider :value="storyDocument.settings.imageMaxWidthPercent" :min="20" :max="100" :step="5" @update:value="setSetting('imageMaxWidthPercent', $event)" /><span>{{ storyDocument.settings.imageMaxWidthPercent }}%</span></label>
          <label>图片高度上限<n-slider :value="storyDocument.settings.imageMaxHeightVh" :min="25" :max="90" :step="5" @update:value="setSetting('imageMaxHeightVh', $event)" /><span>{{ storyDocument.settings.imageMaxHeightVh }}vh</span></label>
        </section>
      </footer>

      <Teleport to="body"><div v-if="editingPerformanceMessage" class="performance-modal" @click.self="closePerformanceEditor"><form @submit.prevent="savePerformance">
        <header><strong>消息演出编排</strong><button type="button" @click="closePerformanceEditor">✕</button></header>
        <label>完整显示时长<n-input-number v-model:value="performanceForm.durationMs" clearable :min="0" :max="120000" :step="100" placeholder="跟随默认" /><span>ms</span></label>
        <label v-if="editingPerformanceMessage.kind === 'text'">流式输出<n-select v-model:value="performanceForm.streamMode" :options="streamModeOptions" /></label>
        <template v-if="editingPerformanceMessage.kind === 'image'"><label class="switch-row"><span>自动打开图片</span><n-switch v-model:value="performanceForm.imagePreviewEnabled" /></label><label v-if="performanceForm.imagePreviewEnabled">出现后打开<n-input-number v-model:value="performanceForm.imageOpenAfterMs" :min="0" :max="60000" :step="100" /><span>ms</span></label><label v-if="performanceForm.imagePreviewEnabled">查看后关闭<n-input-number v-model:value="performanceForm.imageDurationMs" :min="250" :max="120000" :step="250" /><span>ms</span></label></template>
        <section v-if="editingPerformanceMessage.kind === 'text'" class="token-timing"><div><strong>逐词额外停顿</strong><small>按完整英文单词和中文词段切分，不会吐出半个单词。</small></div><label v-for="token in performanceTokens" :key="token.index"><code>{{ token.text.trim() || '空格' }}</code><n-input-number :value="performanceForm.tokenDelays[token.index]" clearable :min="0" :max="30000" :step="50" placeholder="默认" @update:value="setTokenDelay(token.index, $event)" /><span>ms</span></label></section>
        <footer><button type="button" class="danger" @click="clearPerformance">清除编排</button><span></span><button type="button" @click="closePerformanceEditor">取消</button><button class="primary" type="submit">保存</button></footer>
      </form></div></Teleport>

      <StoryImageViewer :show="imageViewerOpen" :src="imageViewerSrc" :alt="imageViewerAlt" :canvas-width="storyDocument.settings.canvasWidth" :auto-close-ms="imageViewerAutoCloseMs" @close="closeImageViewer" />
    </div>
  </Teleport>
</template>

<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, reactive, ref, toRaw, watch } from "vue";
import StoryImageViewer from "./StoryImageViewer.vue";
import { playbackDelay, segmentStoryText, storyDisplayText, storyMessageGroupPosition } from "~/story/model";
import type { StoryArchive, StoryAssetRef, StoryCharacter, StoryMessage, StorySettings } from "~/story/types";

const props = defineProps<{ show: boolean; archive: StoryArchive; assetUrl: (id: string) => string }>();
const emit = defineEmits<{ close: []; change: [StoryArchive] }>();
const storyDocument = computed(() => props.archive.document);
const scrollEl = ref<HTMLElement>();
const visibleCount = ref(storyDocument.value.messages.length);
const started = ref(false); const paused = ref(false); const phase = ref<"idle" | "typing" | "streaming">("idle");
const streamedMessageId = ref(""); const streamedText = ref(""); const streamTokenIndex = ref(0);
const performanceEditMode = ref(false); const displaySettingsOpen = ref(false); const performanceSettingsOpen = ref(false); const titleDraft = ref(storyDocument.value.title);
const editingPerformanceMessage = ref<StoryMessage | null>(null);
const imageViewerOpen = ref(false); const imageViewerSrc = ref(""); const imageViewerAlt = ref(""); const imageViewerAutoCloseMs = ref(0);
const performanceForm = reactive({ durationMs: null as number | null, streamMode: "inherit" as "inherit" | "on" | "off", tokenDelays: {} as Record<number, number>, imagePreviewEnabled: false, imageOpenAfterMs: 0, imageDurationMs: 3000 });
let timer = 0; let imageTimer = 0; let previousPageOverflow = "";
const timingOptions = [{ label: "按字数动态", value: "dynamic" }, { label: "固定间隔", value: "fixed" }];
const typingEffectOptions = [{ label: "跳动省略号", value: "dots" }, { label: "轻微呼吸", value: "pulse" }, { label: "波浪点阵", value: "wave" }];
const streamModeOptions = [{ label: "跟随全局", value: "inherit" }, { label: "本条开启", value: "on" }, { label: "本条关闭", value: "off" }];
const visibleMessages = computed(() => performanceEditMode.value || !started.value ? storyDocument.value.messages : storyDocument.value.messages.slice(0, visibleCount.value));
const finished = computed(() => started.value && visibleCount.value >= storyDocument.value.messages.length && phase.value === "idle");
const typingCharacter = computed(() => character(storyDocument.value.messages[visibleCount.value]?.characterId || ""));
const performanceTokens = computed(() => { const message = editingPerformanceMessage.value; return message?.kind === "text" ? segmentStoryText(displayText(message.text)).filter((token) => token.text.trim()) : []; });
const canvasStyle = computed(() => ({ "--canvas-width": `${storyDocument.value.settings.canvasWidth}px`, "--bubble-width": `${Math.round(720 * storyDocument.value.settings.bubbleMaxWidth / 100)}px`, "--font-size": `${storyDocument.value.settings.fontSize}px`, "--avatar-size": `${storyDocument.value.settings.avatarSize}px`, "--narrator-avatar-size": `${storyDocument.value.settings.narratorAvatarSize}px`, "--side-gutter": `${storyDocument.value.settings.centerGutterPercent / 2}%`, "--image-max-width": `${Math.round(storyDocument.value.settings.canvasWidth * storyDocument.value.settings.imageMaxWidthPercent / 100)}px`, "--image-max-height": `${storyDocument.value.settings.imageMaxHeightVh}vh` }));
const playerStyle = computed(() => ({ "--animation-duration": `${storyDocument.value.settings.animationDurationMs}ms` }));

function cloneArchive(): StoryArchive { return { document: structuredClone(toRaw(storyDocument.value)), assets: new Map(toRaw(props.archive.assets)) }; }
function update(mutator: (archive: StoryArchive) => void) { const archive = cloneArchive(); mutator(archive); archive.document.updatedAt = new Date().toISOString(); emit("change", archive); }
function setSetting<K extends keyof StorySettings>(key: K, value: StorySettings[K]) { update((archive) => { archive.document.settings[key] = value; }); }
function saveTitle() { const value = titleDraft.value.trim(); if (!value) { titleDraft.value = storyDocument.value.title; return; } update((archive) => { archive.document.title = value; }); }
function character(id: string) { return storyDocument.value.characters.find((item) => item.id === id); }
function assetUrl(asset?: StoryAssetRef) { return asset ? (props.archive.assets.has(asset.id) ? props.assetUrl(asset.id) : asset.sourceUrl || asset.id) : ""; }
function avatar(value?: StoryCharacter) { return assetUrl(value?.avatar) || (value?.imUserId ? `/api/editor/avatar/qq/${encodeURIComponent(value.imUserId)}` : ""); }
function imageUrl(asset: StoryAssetRef) { return assetUrl(asset); }
function nameStyle(value?: StoryCharacter) { return value?.color ? { color: value.color } : undefined; }
function displayText(text: string) { return storyDisplayText(text, storyDocument.value.settings.preserveLineBreaks); }
function groupPosition(index: number) { return storyMessageGroupPosition({ ...storyDocument.value, messages: visibleMessages.value }, index); }
function groupStarts(index: number) { return ["single", "first"].includes(groupPosition(index)); }
function isDefaultNarrator(value?: StoryCharacter) { return !!(value?.position === "narrator" && value.name.trim() === "旁白" && !value.avatar && !value.imUserId); }
function avatarSlot(id: string) { const value = character(id); return storyDocument.value.settings.showAvatars && !value?.isNarrator && value?.position !== "narrator"; }
function showAvatar(id: string, index: number) { if (!avatarSlot(id)) return false; const position = groupPosition(index); return storyDocument.value.settings.avatarAlignment === "bottom" ? ["single", "last"].includes(position) : ["single", "first"].includes(position); }
function showOutsideName(id: string, index: number) { const value = character(id); return !!(storyDocument.value.settings.showNames && groupStarts(index) && value?.position !== "narrator"); }
function showNarratorBubbleAvatar(id: string, index: number) { const value = character(id); return !!(storyDocument.value.settings.showAvatars && !value?.isNarrator && value?.position === "narrator" && value.narratorAvatar && !isDefaultNarrator(value) && groupStarts(index)); }
function showNarratorName(id: string, index: number) { return !!(storyDocument.value.settings.showNames && storyDocument.value.settings.showNarratorNames && showNarratorBubbleAvatar(id, index)); }
function messageTime(message: StoryMessage) { if (message.timeText) return message.timeText; if (!message.time) return "--:--"; const value = message.time > 10_000_000_000 ? message.time : message.time * 1000; return new Date(value).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }); }
function hasPerformance(message: StoryMessage) { return !!message.performance && Object.keys(message.performance).length > 0; }
function performanceSummary(message: StoryMessage) { const parts: string[] = []; if (message.performance?.durationMs != null) parts.push(`${message.performance.durationMs}ms`); if (message.performance?.stream != null) parts.push(message.performance.stream ? "流式" : "整条"); if (message.performance?.tokenDelays && Object.keys(message.performance.tokenDelays).length) parts.push("逐词"); if (message.performance?.imagePreview) parts.push(`看图 ${message.performance.imagePreview.durationMs}ms`); return parts.join(" · "); }
function renderedText(message: StoryMessage) { return message.kind === "text" && streamedMessageId.value === message.id ? streamedText.value : message.kind === "text" ? displayText(message.text) : ""; }
function stopTimers() { window.clearTimeout(timer); window.clearTimeout(imageTimer); }
function scrollBottom() { nextTick(() => scrollEl.value?.scrollTo({ top: scrollEl.value.scrollHeight, behavior: "smooth" })); }
function randomPause() { const min = storyDocument.value.settings.streamPauseMinMs; const max = Math.max(min, storyDocument.value.settings.streamPauseMaxMs); return min + Math.round(Math.random() * (max - min)); }
function shouldStream(message: StoryMessage) { return message.kind === "text" && (message.performance?.stream ?? storyDocument.value.settings.streamEnabled); }
function holdDelay(message: StoryMessage) { if (message.performance?.durationMs != null) return message.performance.durationMs; if (storyDocument.value.settings.playbackTiming === "fixed") return storyDocument.value.settings.fixedDelayMs; return playbackDelay(message, storyDocument.value); }
function scheduleAfter(message: StoryMessage) { phase.value = "idle"; streamedMessageId.value = ""; if (!storyDocument.value.settings.autoplay || paused.value || finished.value) return; timer = window.setTimeout(revealNext, holdDelay(message)); }
function emitNextToken(message: StoryMessage, tokens: ReturnType<typeof segmentStoryText>) { if (paused.value || phase.value !== "streaming") return; const token = tokens[streamTokenIndex.value]; if (!token) { streamedText.value = displayText(message.kind === "text" ? message.text : ""); scheduleAfter(message); return; } streamedText.value += token.text; const extra = message.performance?.tokenDelays?.[token.index] || 0; const base = 1000 / Math.max(1, storyDocument.value.settings.streamTokensPerSecond); const pause = token.pauseEligible ? randomPause() : 0; streamTokenIndex.value += 1; scrollBottom(); timer = window.setTimeout(() => emitNextToken(message, tokens), base + pause + extra); }
function revealMessage(message: StoryMessage) { visibleCount.value += 1; scrollBottom(); if (message.kind === "image") { const event = message.performance?.imagePreview; if (event) imageTimer = window.setTimeout(() => openImage(message, event.durationMs), event.openAfterMs); scheduleAfter(message); return; } if (!shouldStream(message)) { scheduleAfter(message); return; } const tokens = segmentStoryText(displayText(message.text)); streamedMessageId.value = message.id; streamedText.value = ""; streamTokenIndex.value = 0; phase.value = "streaming"; emitNextToken(message, tokens); }
function revealNext() { stopTimers(); if (!started.value || paused.value || visibleCount.value >= storyDocument.value.messages.length) return; const message = storyDocument.value.messages[visibleCount.value]; if (!message) return; if (storyDocument.value.settings.typingIndicatorEnabled && storyDocument.value.settings.typingIndicatorMs > 0) { phase.value = "typing"; scrollBottom(); timer = window.setTimeout(() => revealMessage(message), storyDocument.value.settings.typingIndicatorMs); } else revealMessage(message); }
function completeCurrentStream() { const message = storyDocument.value.messages[Math.max(0, visibleCount.value - 1)]; if (!message || message.kind !== "text") return; stopTimers(); streamedText.value = displayText(message.text); scheduleAfter(message); }
function startPlayback() { stopTimers(); performanceEditMode.value = false; displaySettingsOpen.value = false; performanceSettingsOpen.value = false; started.value = true; paused.value = false; visibleCount.value = 0; phase.value = "idle"; streamedMessageId.value = ""; nextTick(() => scrollEl.value?.scrollTo({ top: 0 })); revealNext(); }
function stopPlayback() { stopTimers(); closeImageViewer(); started.value = false; paused.value = false; phase.value = "idle"; streamedMessageId.value = ""; visibleCount.value = storyDocument.value.messages.length; scrollBottom(); }
function headerAction() { if (!started.value || finished.value) { startPlayback(); return; } paused.value = !paused.value; stopTimers(); if (!paused.value) { if (phase.value === "streaming") completeCurrentStream(); else revealNext(); } }
function advanceFromCanvas() { if (performanceEditMode.value || !started.value || paused.value || finished.value || imageViewerOpen.value) return; if (phase.value === "typing") { const message = storyDocument.value.messages[visibleCount.value]; stopTimers(); if (message) revealMessage(message); return; } if (phase.value === "streaming") { completeCurrentStream(); return; } revealNext(); }
function onMessageClick(message: StoryMessage) { if (performanceEditMode.value) openPerformanceEditor(message); else advanceFromCanvas(); }
function togglePerformanceEdit() { stopTimers(); started.value = false; paused.value = false; phase.value = "idle"; visibleCount.value = storyDocument.value.messages.length; performanceEditMode.value = !performanceEditMode.value; titleDraft.value = storyDocument.value.title; displaySettingsOpen.value = false; performanceSettingsOpen.value = false; }
function toggleDisplaySettings() { performanceSettingsOpen.value = false; displaySettingsOpen.value = !displaySettingsOpen.value; }
function togglePerformanceSettings() { displaySettingsOpen.value = false; performanceSettingsOpen.value = !performanceSettingsOpen.value; }
function openPerformanceEditor(message: StoryMessage) { editingPerformanceMessage.value = message; performanceForm.durationMs = message.performance?.durationMs ?? null; performanceForm.streamMode = message.performance?.stream == null ? "inherit" : message.performance.stream ? "on" : "off"; performanceForm.tokenDelays = { ...(message.performance?.tokenDelays || {}) }; performanceForm.imagePreviewEnabled = !!message.performance?.imagePreview; performanceForm.imageOpenAfterMs = message.performance?.imagePreview?.openAfterMs ?? 0; performanceForm.imageDurationMs = message.performance?.imagePreview?.durationMs ?? 3000; }
function closePerformanceEditor() { editingPerformanceMessage.value = null; }
function setTokenDelay(index: number, value: number | null) { if (value == null || value <= 0) delete performanceForm.tokenDelays[index]; else performanceForm.tokenDelays[index] = value; }
function savePerformance() { const id = editingPerformanceMessage.value?.id; if (!id) return; update((archive) => { const target = archive.document.messages.find((message) => message.id === id); if (!target) return; const tokenDelays = Object.fromEntries(Object.entries(performanceForm.tokenDelays).filter(([, value]) => value > 0)); const performance = { ...(performanceForm.durationMs == null ? {} : { durationMs: performanceForm.durationMs }), ...(performanceForm.streamMode === "inherit" ? {} : { stream: performanceForm.streamMode === "on" }), ...(Object.keys(tokenDelays).length ? { tokenDelays } : {}), ...(target.kind === "image" && performanceForm.imagePreviewEnabled ? { imagePreview: { openAfterMs: performanceForm.imageOpenAfterMs, durationMs: performanceForm.imageDurationMs } } : {}) }; target.performance = Object.keys(performance).length ? performance : undefined; }); closePerformanceEditor(); }
function clearPerformance() { const id = editingPerformanceMessage.value?.id; if (!id) return; update((archive) => { const target = archive.document.messages.find((message) => message.id === id); if (target) target.performance = undefined; }); closePerformanceEditor(); }
